window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7fa849354fbe61a0"]={"versions": [{"id": "FIG-7fa849354fbe61a0", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Veranschaulichung des Datenflusses vom Zielsystem (Target ECU) zum externen Host-System innerhalb des AUTOSAR-Debugging-Konzepts (AUTOSAR_SWS_Debugging). Das Diagramm stellt die Interaktion zwischen den Softwaremodulen auf der ECU (Basis-Software / BSW und Debugging-Module) und der externen Debugging-Host-Instanz während eines Upload- bzw. Trace-Vorgangs dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Host</strong>: Externes System / Entwicklungsrechner (symbolisiert durch Arbeitsplatz-Piktogramm und Box „Host“ mit vertikaler Lebenslinie).</li>\n<li><strong>Debugging Com Module</strong>: Kommunikationsmodul für Debugging-Zwecke auf dem Target, beinhaltet die Implementierung eines vereinfachten Transportprotokolls (simplified TP).</li>\n<li><strong>Debugging Core Module</strong>: Zentrales Steuerungsmodul des Debugging-Subsystems auf der ECU.</li>\n<li><strong>BSW</strong>: Basis-Software-Schicht bzw. Quellmodule der ECU, von denen Debug- und Messdaten erhoben werden.</li>\n<li><strong>Schnittstellen & Interaktionen</strong>:</li>\n<li><code>TX request</code>: Asynchroner oder synchroner Übertragungsanstoß vom Debugging Core Module an das Debugging Com Module.</li>\n<li><code>collection of data</code>: Bidirektionale Interaktion / Datenabfrage zwischen Debugging Core Module und BSW.</li>\n<li><code>message fragment 1</code>, <code>message fragment 2</code>, ..., <code>message fragment n</code>: Sequenzielle Übertragung der segmentierten Datenrahmen vom Debugging Com Module zum externen Host.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Das <strong>Debugging Core Module</strong> sendet einen Sendeauftrag (<code>TX request</code>) an das <strong>Debugging Com Module</strong>, wodurch dessen Aktivierungsbalken startet.</li>\n<li>Parallel oder nachfolgend erfolgt der Datenaustausch (<code>collection of data</code>) zwischen dem <strong>Debugging Core Module</strong> und der <strong>BSW</strong> (doppelseitig gerichteter Pfeil zur Datenerfassung).</li>\n<li>Das <strong>Debugging Com Module</strong> fragmentiert die zu sendenden Daten mittels seines integrierten vereinfachten Transportprotokolls (simplified TP) und überträgt die Fragmente sequenziell an den <strong>Host</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>message fragment 1</code></li>\n<li><code>message fragment 2</code></li>\n<li>weitere Fragmente bis hin zu <code>message fragment n</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Mit dem Versand des letzten Fragments endet der Aktivierungsbereich des Debugging Com Module.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Schaubild veranschaulicht das Prinzip der Datenübertragung von Mess-/Debugdaten bei PDU-Größenbeschränkungen des zugrundeliegenden physikalischen Kommunikationsbusses.</li>\n<li>Das <code>Debugging Com Module</code> muss eine eigenständige, leichtgewichtige Transportprotokoll-Logik (<code>simplified TP</code>) bereitstellen, um Nutzdaten in mehrere Fragmente (<code>message fragment 1..n</code>) aufzuteilen und ohne vollen AUTOSAR-PDU-Router-/TP-Stack-Overhead an das Host-System zu übertragen.</li>\n<li>Die Erfassung von Laufzeitdaten (<code>collection of data</code>) aus den BSW-Modulen wird vom <code>Debugging Core Module</code> orchestriert und entkoppelt vom Fragmentierungs- und Übertragungsprozess des <code>Debugging Com Module</code> abgewickelt.</li>\n</ul>"}, {"id": "FIG-12e97d1bf41b645f", "releases": ["R4.1.3", "R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Veranschaulichung des Datenflusses vom Zielsystem (Target ECU) zum externen Host-System innerhalb des AUTOSAR-Debugging-Konzepts (AUTOSAR_SWS_Debugging). Das Diagramm stellt die Interaktion zwischen den Softwaremodulen auf der ECU (Basis-Software / BSW und Debugging-Module) und der externen Debugging-Host-Instanz während eines Upload- bzw. Trace-Vorgangs dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Host</strong>: Externes System / Entwicklungsrechner (symbolisiert durch Arbeitsplatz-Piktogramm und Box „Host“ mit vertikaler Lebenslinie).</li>\n<li><strong>Debugging Com Module</strong>: Kommunikationsmodul für Debugging-Zwecke auf dem Target, beinhaltet die Implementierung eines vereinfachten Transportprotokolls (simplified TP).</li>\n<li><strong>Debugging Core Module</strong>: Zentrales Steuerungsmodul des Debugging-Subsystems auf der ECU.</li>\n<li><strong>BSW</strong>: Basis-Software-Schicht bzw. Quellmodule der ECU, von denen Debug- und Messdaten erhoben werden.</li>\n<li><strong>Schnittstellen & Interaktionen</strong>:</li>\n<li><code>TX request</code>: Asynchroner oder synchroner Übertragungsanstoß vom Debugging Core Module an das Debugging Com Module.</li>\n<li><code>collection of data</code>: Bidirektionale Interaktion / Datenabfrage zwischen Debugging Core Module und BSW.</li>\n<li><code>message fragment 1</code>, <code>message fragment 2</code>, ..., <code>message fragment n</code>: Sequenzielle Übertragung der segmentierten Datenrahmen vom Debugging Com Module zum externen Host.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Das <strong>Debugging Core Module</strong> sendet einen Sendeauftrag (<code>TX request</code>) an das <strong>Debugging Com Module</strong>, wodurch dessen Aktivierungsbalken startet.</li>\n<li>Parallel oder nachfolgend erfolgt der Datenaustausch (<code>collection of data</code>) zwischen dem <strong>Debugging Core Module</strong> und der <strong>BSW</strong> (doppelseitig gerichteter Pfeil zur Datenerfassung).</li>\n<li>Das <strong>Debugging Com Module</strong> fragmentiert die zu sendenden Daten mittels seines integrierten vereinfachten Transportprotokolls (simplified TP) und überträgt die Fragmente sequenziell an den <strong>Host</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>message fragment 1</code></li>\n<li><code>message fragment 2</code></li>\n<li>weitere Fragmente bis hin zu <code>message fragment n</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Mit dem Versand des letzten Fragments endet der Aktivierungsbereich des Debugging Com Module.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Schaubild veranschaulicht das Prinzip der Datenübertragung von Mess-/Debugdaten bei PDU-Größenbeschränkungen des zugrundeliegenden physikalischen Kommunikationsbusses.</li>\n<li>Das <code>Debugging Com Module</code> muss eine eigenständige, leichtgewichtige Transportprotokoll-Logik (<code>simplified TP</code>) bereitstellen, um Nutzdaten in mehrere Fragmente (<code>message fragment 1..n</code>) aufzuteilen und ohne vollen AUTOSAR-PDU-Router-/TP-Stack-Overhead an das Host-System zu übertragen.</li>\n<li>Die Erfassung von Laufzeitdaten (<code>collection of data</code>) aus den BSW-Modulen wird vom <code>Debugging Core Module</code> orchestriert und entkoppelt vom Fragmentierungs- und Übertragungsprozess des <code>Debugging Com Module</code> abgewickelt.</li>\n</ul>"}], "trans": [{"from": "FIG-7fa849354fbe61a0", "to": "FIG-12e97d1bf41b645f", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
